package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import net.minecraft.block.BlockLiquid;
import net.minecraft.block.BlockTrapDoor;
import net.minecraft.nbt.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.*;
import net.minecraftforge.fluids.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Actual final opening surfaces: joined compartments, neighbors, corner heights and source surface order. */
public final class TrapdoorFluidSurfaceLegacyChecks {
    private static final class Seed {final boolean diagonal;final int position,flags;final EnumFacing face;Seed(boolean diagonal,int position,EnumFacing face,int flags){this.diagonal=diagonal;this.position=position;this.face=face;this.flags=flags;}}
    private static JsonArray numbers(double... values){JsonArray out=new JsonArray();for(double value:values)out.add(value);return out;}
    private static void bits(MessageDigest hash,long value){for(int n=56;n>=0;n-=8)hash.update((byte)(value>>>n));}private static void number(MessageDigest hash,double value){bits(hash,Double.doubleToRawLongBits(value));}private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte value:bytes)out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
    private static String key(double[] plane){StringBuilder out=new StringBuilder();for(double value:plane)out.append(Long.toHexString(Double.doubleToRawLongBits(value))).append('/');return out.toString();}
    private static void stored(TileEntityProgrammableTrapdoor tile,int pair){int first=pair==1?0:pair==5?2:1,second=pair==0?0:pair>=4?2:1;TrapdoorFluidLegacyChecks.stored(tile,first,second);if(pair==3){NBTTagCompound tag=new NBTTagCompound();tile.fluids.write(tag);tag.getCompoundTag("ContainedFluids").getCompoundTag("Side1").getCompoundTag("Tag").setInteger("FixtureKind",99);tile.fluids.read(tag);}}
    private static FluidStack[] fluids(NonRenderingChecks.MemoryWorld world,BlockPos pos){return new FluidStack[]{WaterloggedParts.fluid(world,pos,0),WaterloggedParts.fluid(world,pos,1)};}
    private static JsonObject descriptor(NonRenderingChecks.MemoryWorld world,BlockPos pos){JsonObject out=new JsonObject();FluidStack[] fluids=fluids(world,pos);int present=(fluids[0]==null?0:1)|(fluids[1]==null?0:2);boolean open=OpeningFluids.open(world,pos);out.add("plane",numbers(OpeningFluids.plane(world,pos)));out.addProperty("open",open);out.addProperty("present",present);out.addProperty("joined",open&&fluids[0]!=null&&fluids[0].isFluidEqual(fluids[1]));for(int side=0;side<2;side++){boolean covered=false;if(fluids[side]!=null){BlockPos above=pos.up();covered=WaterloggedParts.nativeFluid(world.getBlockState(above))==fluids[side].getFluid();if(!covered&&WaterloggedParts.supports(world.getBlockState(above)))covered=fluids[side].isFluidEqual(WaterloggedParts.fluid(world,above,0))||fluids[side].isFluidEqual(WaterloggedParts.fluid(world,above,1));}if(world.getBlockState(pos).getBlock() instanceof BlockConfigurableSpaceDoor&&!covered)out.addProperty("height"+side,.999);else out.addProperty("height"+side,1);}return out;}
    static int emit(NonRenderingChecks.MemoryWorld world,BlockPos pos,net.minecraft.tileentity.TileEntity owner,int basis,int pair,int neighbor,java.io.PrintWriter out,MessageDigest corpus)throws Exception{
            JsonObject row=new JsonObject();row.addProperty("basis",basis);row.addProperty("pair",pair);row.addProperty("neighbor",neighbor);row.add("origin",numbers(pos.getX(),pos.getY(),pos.getZ()));row.add("own",descriptor(world,pos));FluidStack[] own=fluids(world,pos);JsonArray heights=new JsonArray();for(int side=0;side<2;side++)heights.add(own[side]==null?JsonNull.INSTANCE:numbers(ContainedFluidHeights.corner(world,pos,own[side].getFluid(),0,0),ContainedFluidHeights.corner(world,pos,own[side].getFluid(),0,1),ContainedFluidHeights.corner(world,pos,own[side].getFluid(),1,1),ContainedFluidHeights.corner(world,pos,own[side].getFluid(),1,0)));row.add("corners",heights);
            JsonArray neighbors=new JsonArray();for(EnumFacing direction:EnumFacing.values()){BlockPos at=pos.offset(direction);net.minecraft.block.state.IBlockState state=world.getBlockState(at);boolean supported=OpeningFluids.supports(state)&&WaterloggedParts.wet(world,at);JsonObject entry=new JsonObject();if(supported)entry.add("region",descriptor(world,at));FluidStack[] adjacent=supported?fluids(world,at):new FluidStack[2];JsonArray matches=new JsonArray(),hidden=new JsonArray();for(int side=0;side<2;side++){JsonArray match=new JsonArray();for(int other=0;other<2;other++)match.add(own[side]!=null&&own[side].isFluidEqual(adjacent[other]));matches.add(match);hidden.add(own[side]!=null&&(WaterloggedParts.nativeFluid(state)==own[side].getFluid()||state.doesSideBlockRendering(world,at,direction.getOpposite())));}entry.add("matches",matches);entry.add("hidden",hidden);neighbors.add(entry);}row.add("neighbors",neighbors);
            java.util.List<WaterloggedSurfaceMesh.Surface> mesh=WaterloggedSurfaceMesh.entry(owner).mesh;MessageDigest digest=MessageDigest.getInstance("SHA-256");bits(digest,mesh.size());for(WaterloggedSurfaceMesh.Surface surface:mesh){bits(digest,surface.side);bits(digest,surface.axis);bits(digest,surface.boundary==null?-1:surface.boundary.getIndex());number(digest,surface.normal.x);number(digest,surface.normal.y);number(digest,surface.normal.z);bits(digest,surface.vertices.length);for(Vec3d p:surface.vertices){number(digest,p.x);number(digest,p.y);number(digest,p.z);}}row.addProperty("faces",mesh.size());row.addProperty("hash",hex(digest.digest()));String line=row.toString();out.println(line);corpus.update(line.getBytes(StandardCharsets.UTF_8));return mesh.size();
    }
    public static void main(String[] args)throws Exception{
        net.minecraft.init.Bootstrap.register();TrapdoorFluidLegacyChecks.blocks();LinkedHashMap<String,Seed> seeds=new LinkedHashMap<>();BlockPos origin=new BlockPos(8,80,8);
        for(boolean diagonal:new boolean[]{false,true})for(int position=0;position<3;position++)for(EnumFacing face:EnumFacing.HORIZONTALS)for(int flags=0;flags<32;flags++){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(true);TrapdoorFluidLegacyChecks.setup(world,origin,diagonal,position,face,flags,false);seeds.putIfAbsent(key(OpeningFluids.plane(world,origin)),new Seed(diagonal,position,face,flags));}
        if(seeds.size()!=27)throw new AssertionError("Source closed-plane basis changed "+seeds.size());Path file=Paths.get(args[0]);Files.createDirectories(file.toAbsolutePath().getParent());MessageDigest corpus=MessageDigest.getInstance("SHA-256");int cases=0,total=0;try(java.io.PrintWriter out=new java.io.PrintWriter(Files.newBufferedWriter(file))){
        for(Seed seed:seeds.values())for(boolean open:new boolean[]{false,true})for(int pair=0;pair<6;pair++)for(int neighbor=0;neighbor<8;neighbor++)for(BlockPos pos:new BlockPos[]{origin,new BlockPos(29999967,200,-29999967)}){
            NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(true);TileEntityProgrammableTrapdoor owner=TrapdoorFluidLegacyChecks.setup(world,pos,seed.diagonal,seed.position,seed.face,seed.flags,open);stored(owner,pair);
            if(neighbor==1)world.setBlockState(pos.north(),net.minecraft.init.Blocks.WATER.getDefaultState(),2);if(neighbor==2)world.setBlockState(pos.west(),net.minecraft.init.Blocks.STONE.getDefaultState(),2);if(neighbor==6)world.setBlockState(pos.up(),net.minecraft.init.Blocks.LAVA.getDefaultState(),2);if(neighbor==7)world.setBlockState(pos.north(),net.minecraft.init.Blocks.FLOWING_WATER.getDefaultState().withProperty(BlockLiquid.LEVEL,3),2);
            if(neighbor>=3&&neighbor<=5){BlockPos at=neighbor==3?pos.up():neighbor==4?pos.west():pos.east();TileEntityProgrammableTrapdoor other=TrapdoorFluidLegacyChecks.setup(world,at,false,1,EnumFacing.NORTH,0,neighbor==5);stored(other,neighbor==4?0:2);if(neighbor==4){NBTTagCompound tag=new NBTTagCompound();other.fluids.write(tag);tag.getCompoundTag("ContainedFluids").getCompoundTag("Side0").getCompoundTag("Tag").setInteger("FixtureKind",99);other.fluids.read(tag);}}
            total+=emit(world,pos,owner,cases/(2*6*8*2),pair,neighbor,out,corpus);cases++;
        }}String golden=hex(corpus.digest());if(cases!=5184||total!=39280||!golden.equals("b2cef3eb0dcd3fef0010738c7b9e164f0e86d9d3ddff302f26a0c55993a3651c"))throw new AssertionError("Final surface corpus changed "+cases+"/"+total+"/"+golden);System.out.println("Actual Trapdoor final fluid surfaces PASS basis="+seeds.size()+" cases="+cases+" faces="+total+" golden="+golden);
    }
}
